{{!-- Styling parameters: class, titleClass, descriptionClass, metaClass, imageClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Component: Post Header | Usage: inside {{#post}} --}}
<header class="ghcn-post-header{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}} ghcn-container">
    {{#if primary_tag}}<a class="ghcn-badge" href="{{primary_tag.url}}">{{primary_tag.name}}</a>{{/if}}
    <h1 class="ghcn-post-header__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{title}}</h1>
    {{#if custom_excerpt}}<p class="ghcn-post-header__excerpt{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{custom_excerpt}}</p>{{/if}}
    <div class="ghcn-post-header__meta{{#if ghostcnStyles.metaClass}} {{ghostcnStyles.metaClass}}{{/if}}">
        {{#primary_author}}
            <a class="ghcn-post-header__author" href="{{url}}">
                {{#if profile_image}}<img class="ghcn-avatar" src="{{img_url profile_image size="xs"}}" alt="" />{{/if}}
                <span>{{name}}</span>
            </a>
        {{/primary_author}}
        <span aria-hidden="true">&bull;</span>
        <time datetime="{{date format="YYYY-MM-DD"}}">{{date format="D MMM YYYY"}}</time>
        <span aria-hidden="true">&bull;</span>
        <span>{{reading_time}}</span>
    </div>
    {{#if feature_image}}
        <figure class="ghcn-post-header__media">
            <img class="ghcn-post-header__image{{#if ghostcnStyles.imageClass}} {{ghostcnStyles.imageClass}}{{/if}}" srcset="{{img_url feature_image size="s"}} 400w, {{img_url feature_image size="m"}} 750w, {{img_url feature_image size="l"}} 1200w, {{img_url feature_image size="xl"}} 2000w" sizes="(min-width: 1200px) 1120px, 92vw" src="{{img_url feature_image size="xl"}}" alt="{{#if feature_image_alt}}{{feature_image_alt}}{{else}}{{title}}{{/if}}" />
            {{#if feature_image_caption}}<figcaption>{{feature_image_caption}}</figcaption>{{/if}}
        </figure>
    {{/if}}
</header>
{{/with}}

/* ghostcn: Post Header */
.ghcn-post-header { box-sizing: border-box; margin-block: 4em 2.5em; color: var(--foreground); text-align: center; font-family: inherit; font-size: 16px; line-height: 1.5; isolation: isolate; }
.ghcn-post-header *, .ghcn-post-header *::before, .ghcn-post-header *::after { box-sizing: border-box; }
.ghcn-post-header h1 { max-width: 58em; margin: 1em auto; font-size: clamp(2.5em,7vw,5em); line-height: 0.98; letter-spacing: -0.055em; text-wrap: balance; }
.ghcn-post-header__excerpt { max-width: 44em; margin: 1.25em auto; color: var(--muted-foreground); font-size: clamp(1.05em,2vw,1.25em); }
.ghcn-post-header__meta, .ghcn-post-header__author { display: flex; align-items: center; justify-content: center; gap: 0.625em; }
.ghcn-post-header__meta { flex-wrap: wrap; color: var(--muted-foreground); font-size: 0.8125em; }
.ghcn-post-header__author { color: var(--foreground); font-weight: 700; text-decoration: none; }
.ghcn-post-header__author .ghcn-avatar { width: 2em; height: 2em; }
.ghcn-post-header__media { margin: 3em 0 0; }
.ghcn-post-header__media img { display: block; width: 100%; max-height: 44em; border-radius: min(var(--radius),1.25em); object-fit: cover; }
.ghcn-post-header__media figcaption { margin-top: 0.75em; color: var(--muted-foreground); font-size: 0.75em; }
